    [16841]={name="Earthfury Vestments",sourceType="boss_drop",instructions="Drops from Golemagg the Incinerator in Molten Core.",zone="Molten Core",npc="Golemagg the Incinerator",lore="A core rager grown past all the others, flanked by two hounds that cannot be killed while he stands."},
