    [19830]={name="Zandalar Augur's Bracers",sourceType="quest_reward",instructions="Reward from the quest “Paragons of Power: The Augur's Bracers”. In Zul'Gurub.",zone="Zul'Gurub",questName="Paragons of Power: The Augur's Bracers",lore="They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people. As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe."},
    [19856]={name="The Eye of Hakkar",sourceType="boss_drop",instructions="Drops from Hakkar in Zul'Gurub.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
    [19857]={name="Cloak of Consumption",sourceType="boss_drop",instructions="Drops from Hakkar in Zul'Gurub.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
