    [20216]={name="Belt of Preserved Heads",sourceType="quest_reward",instructions="Reward from the quest “A Collection of Heads” — pick it over the other choices. In Zul'Gurub.",zone="Zul'Gurub",questName="A Collection of Heads",lore="He must be stopped! Take this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy."},
